function Ensure-PythonRunner {
    if (Get-PythonCommand) { return }
    $uv = Get-Command 'uv.exe' -ErrorAction SilentlyContinue
    if (-not $uv) {
        Step 'Installing standalone uv for the native Python LazyDev CLI'
        $tempUv = Join-Path ([IO.Path]::GetTempPath()) ("lazydev-uv-install-" + [guid]::NewGuid().ToString('N') + '.ps1')
        try {
            Invoke-WebRequest -UseBasicParsing -Uri 'https://astral.sh/uv/install.ps1' -OutFile $tempUv
            & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $tempUv
            if ($LASTEXITCODE -ne 0) { Fail "uv installer exited with code $LASTEXITCODE." }
        } finally {
            Remove-Item -LiteralPath $tempUv -Force -ErrorAction SilentlyContinue
        }
        $uv = Get-Command 'uv.exe' -ErrorAction SilentlyContinue
    }
    if (-not $uv) { Fail 'Python was not found and standalone uv could not be installed.' }
    Write-Host '✓ uv is available as the Python bootstrapper.'
}
function Test-LazyDevSourceCurrent([string]$SourceDir) {
    $py = Join-Path $SourceDir 'cli\lazydev.py'
    $mjs = Join-Path $SourceDir 'scripts\lazydev.mjs'
    if (-not (Test-Path -LiteralPath $py -PathType Leaf)) { return $false }
    if (-not (Test-Path -LiteralPath $mjs -PathType Leaf)) { return $false }
    try {
        $pyText = Get-Content -Raw -LiteralPath $py
        $mjsText = Get-Content -Raw -LiteralPath $mjs
        return (
            $pyText -match 'lazydev resume' -and
            $pyText -match 'if\s+cmd\s*==\s*["'']resume["'']:' -and
            $pyText -match 'return chat\(resume=True\)' -and
            $pyText -match 'def _discover_command\(' -and
            $pyText -match 'def _resolve_from_dirs\(' -and
            $pyText -match 'def _managed_which\(' -and
            $pyText -match 'def find_kimi\(' -and
            $pyText -match 'def find_codex\(' -and
            $pyText -match 'def find_antigravity\(' -and
            $pyText -match 'response\.output_item\.done' -and
            $pyText -match '_lazydev_dev_mcp_entry' -and
            (Test-Path -LiteralPath (Join-Path $SourceDir 'runtime\lazydev-dev-mcp.py') -PathType Leaf) -and
            $pyText -notmatch '["'']--config["'']' -and
            $mjsText -match 'resume' -and
            $mjsText -notmatch 'cmd\s*===\s*["'']sessions["'']'
        )
    } catch { return $false }
}

function Find-NodeCommand {
    foreach ($name in @('node.exe','node')) {
        $cmd = Get-Command $name -ErrorAction SilentlyContinue
        if ($cmd) { return $cmd.Source }
    }
    return $null
}
function Find-NpmCommand {
    foreach ($name in @('npm.cmd','npm.exe','npm')) {
        $cmd = Get-Command $name -ErrorAction SilentlyContinue
        if ($cmd) { return $cmd.Source }
    }
    return $null
}
function Test-CliUiPackage {
    $pkg = Join-Path $LazyDevUiHome 'node_modules\@poppinss\cliui\package.json'
    if (-not (Test-Path -LiteralPath $pkg -PathType Leaf)) { return $false }
    try {
        return (((Get-Content -Raw -LiteralPath $pkg) | ConvertFrom-Json).version -eq $LazyDevUiVersion)
    } catch { return $false }
}
function Test-CliUiRuntime {
    if (-not (Test-CliUiPackage)) { return $false }
    $node = Find-NodeCommand
    if (-not $node) { return $false }
    Push-Location $LazyDevUiHome
    try {
        & $node --input-type=module -e "import('@poppinss/cliui').then(m=>{if(typeof m.cliui!=='function')process.exit(2)}).catch(()=>process.exit(3))" *> $null
        return ($LASTEXITCODE -eq 0) -and (Test-Path -LiteralPath (Join-Path $LazyDevUiHome 'lazydev-ui.mjs') -PathType Leaf)
    } finally { Pop-Location }
}
function Install-CliUiRuntime {
    $node = Find-NodeCommand
    $npm = Find-NpmCommand
    if (-not $node -or -not $npm) {
        Write-Host "CLI UI helper $LazyDevUiVersion — skipped (Node.js/npm not available; native AI UIs do not require it)."
        return
    }
    if (Test-CliUiPackage) {
        $sourceHelper = Join-Path $InstallRoot 'runtime\lazydev-ui.mjs'
        if (Test-Path -LiteralPath $sourceHelper -PathType Leaf) {
            Copy-Item -LiteralPath $sourceHelper -Destination (Join-Path $LazyDevUiHome 'lazydev-ui.mjs') -Force
        }
        if (Test-CliUiRuntime) {
            Write-Host "CLI UI helper $LazyDevUiVersion is already current — skipped."
        } else {
            Write-Host "CLI UI helper $LazyDevUiVersion is already installed — skipped npm reinstall; runtime will self-check on use."
        }
        return
    }
    Step "Installing CLI UI helper $LazyDevUiVersion"
    New-Item -ItemType Directory -Path $LazyDevUiHome -Force | Out-Null
    $packagePath = Join-Path $LazyDevUiHome 'package.json'
    Set-Content -LiteralPath $packagePath -Encoding UTF8 -Value (@"
{
  `"name`": `"@blizps/lazydev-ui-runtime`",
  `"private`": true,
  `"dependencies`": { `"$LazyDevUiPackage`": `"$LazyDevUiVersion`" }
}
"@)
    Push-Location $LazyDevUiHome
    try {
        & $npm install --no-package-lock --ignore-scripts --omit=dev
        if ($LASTEXITCODE -ne 0) {
            Write-Host 'CLI UI helper installation failed — native AI UIs remain available without it.'
            return
        }
    } finally { Pop-Location }
    $sourceHelper = Join-Path $InstallRoot 'runtime\lazydev-ui.mjs'
    if (Test-Path -LiteralPath $sourceHelper -PathType Leaf) {
        Copy-Item -LiteralPath $sourceHelper -Destination (Join-Path $LazyDevUiHome 'lazydev-ui.mjs') -Force
    }
    if (Test-CliUiRuntime) {
        Write-Host "✓ CLI UI helper $LazyDevUiVersion ready"
    } else {
        Write-Host 'CLI UI helper installed but runtime verification failed — native AI UIs remain available.'
    }
}

function Expand-EmbeddedLazyDevSource([string]$Destination) {
    $payloadPath = Join-Path $Destination 'lazydev-embedded.tgz'
    New-Item -ItemType Directory -Path $Destination -Force | Out-Null
    [IO.File]::WriteAllBytes($payloadPath, [Convert]::FromBase64String(($EmbeddedLazyDevPayload -replace '\s','')))
    $tar = Get-Command tar.exe -ErrorAction SilentlyContinue
    if (-not $tar) { Fail 'Windows tar.exe is required to unpack the embedded LazyDev source.' }
    & $tar.Source -xzf $payloadPath -C $Destination
    if ($LASTEXITCODE -ne 0) { Fail 'Could not unpack the embedded LazyDev source.' }
    Remove-Item -LiteralPath $payloadPath -Force -ErrorAction SilentlyContinue
}

function Get-GitHubRevision {
    $headers = @{ Accept='application/vnd.github+json'; 'X-GitHub-Api-Version'='2022-11-28'; 'User-Agent'='lazy-developer-installer/1.0.2' }
    try {
        $data = Invoke-RestMethod -Headers $headers -Uri $GitHubApiUrl
        if ($data.sha -match '^[0-9a-fA-F]{40}$') { return $data.sha }
    } catch {}
    return $null
}
function Get-LazyDevSourceFingerprint([string]$SourceDir) {
    try {
        $lines = New-Object System.Collections.Generic.List[string]
        Get-ChildItem -LiteralPath $SourceDir -File -Recurse -Force |
            Where-Object { $_.FullName -notmatch '\.git([\\/]|$)' -and $_.FullName -notmatch 'node_modules([\\/]|$)' -and $_.FullName -notmatch '__pycache__([\\/]|$)' -and $_.Extension -ne '.pyc' } |
            Sort-Object FullName | ForEach-Object {
                $hash = (Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()
                $relative = $_.FullName.Substring($SourceDir.Length).TrimStart('\\','/')
                [void]$lines.Add($hash + '  ' + $relative)
            }
        $sha = [Security.Cryptography.SHA256]::Create()
        try {
            $bytes = [Text.Encoding]::UTF8.GetBytes(($lines -join "`n"))
            return ([BitConverter]::ToString($sha.ComputeHash($bytes)) -replace '-', '').ToLowerInvariant()
        } finally { $sha.Dispose() }
    } catch { return '' }
}
function Get-LazyDevLocalSourceRevision([string]$SourceDir) {
    $marker = Join-Path $SourceDir '.lazydev-source-id'
    if (Test-Path -LiteralPath $marker -PathType Leaf) {
        try {
            $id = ((Get-Content -Raw -LiteralPath $marker) -replace '\s', '')
            if ($id) { return 'local-' + $id }
        } catch {}
    }
    return 'local-' + (Get-LazyDevSourceFingerprint $SourceDir)
}
function Get-RtkLatestVersion {
    try {
        $headers = @{ Accept='application/vnd.github+json'; 'User-Agent'='lazy-developer-installer/1.0.2' }
        $data = Invoke-RestMethod -Headers $headers -Uri $RtkApiUrl
        if ($data.tag_name -match '^v(\d+\.\d+\.\d+)$') { return $Matches[1] }
    } catch {}
    return ''
}
function Get-KimiLatestVersion {
    try {
        $headers = @{ Accept='application/vnd.github+json'; 'User-Agent'='lazy-developer-installer/1.0.2' }
        $data = Invoke-RestMethod -Headers $headers -Uri $KimiReleasesApiUrl
        $tag = [string]$data.tag_name
        $m = [regex]::Match($tag, '(\d+\.\d+\.\d+)$')
        if ($m.Success) { return $m.Groups[1].Value }
    } catch {}
    return ''
}
function Get-GitHubReleaseVersion([string]$ApiUrl) {
    try {
        $headers = @{ Accept='application/vnd.github+json'; 'X-GitHub-Api-Version'='2022-11-28'; 'User-Agent'='lazy-developer-installer/1.0.2' }
        $data = Invoke-RestMethod -Headers $headers -Uri $ApiUrl
        $tag = [string]$data.tag_name
        $m = [regex]::Match($tag, '(\d+\.\d+\.\d+)$')
        if ($m.Success) { return $m.Groups[1].Value }
    } catch {}
    return ''
}
function Get-CodexLatestVersion { return Get-GitHubReleaseVersion $CodexReleasesApiUrl }

function Get-CodexReleaseTarget {
    if ($IsWindows) {
        $arch = $env:PROCESSOR_ARCHITECTURE
        if ($env:PROCESSOR_ARCHITEW6432) { $arch = $env:PROCESSOR_ARCHITEW6432 }
        switch ($arch.ToUpperInvariant()) {
            'ARM64' { return 'aarch64-pc-windows-msvc' }
            'AMD64' { return 'x86_64-pc-windows-msvc' }
            default { throw "Unsupported Codex Windows architecture: $arch" }
        }
    }
    throw 'This PowerShell installer path is intended for Windows.'
}

function Invoke-ResilientDownload([string]$Url, [string]$Path) {
    $dir = Split-Path -Parent $Path
    New-Item -ItemType Directory -Force -Path $dir | Out-Null
    $curl = Get-Command curl.exe -ErrorAction SilentlyContinue
    if (-not $curl) { throw 'curl.exe is required for resilient Codex downloads on Windows.' }
    $args = @('--fail','--location','--http1.1','--connect-timeout','20','--max-time','1800','--retry','8','--retry-delay','2','--retry-max-time','1800','--speed-time','90','--speed-limit','1024','--output',$Path)
    if (Test-Path -LiteralPath $Path) {
        & $curl.Source @('--fail','--location','--http1.1','--connect-timeout','20','--max-time','1800','--retry','8','--retry-delay','2','--retry-max-time','1800','--speed-time','90','--speed-limit','1024','--continue-at','-','--output',$Path,$Url)
        if ($LASTEXITCODE -eq 0) { return }
        Remove-Item -LiteralPath $Path -Force -ErrorAction SilentlyContinue
    }
    & $curl.Source @args $Url
    if ($LASTEXITCODE -ne 0) { throw "Download failed: $Url" }
}

function Install-CodexOfficial([string]$Version) {
    $target = Get-CodexReleaseTarget
    $asset = "codex-package-$target.tar.gz"
    $base = "https://github.com/openai/codex/releases/download/rust-v$Version"
    $cacheRoot = if ($env:LOCALAPPDATA) { Join-Path $env:LOCALAPPDATA 'LazyDev\CodexCache' } else { Join-Path $HOME '.lazydev\codex-cache' }
    $versionRoot = Join-Path $cacheRoot $Version
    $archive = Join-Path $versionRoot $asset
    $sums = Join-Path $versionRoot 'codex-package_SHA256SUMS'
    $extract = Join-Path ([IO.Path]::GetTempPath()) ("lazydev-codex-$([guid]::NewGuid().ToString('N'))")
    New-Item -ItemType Directory -Force -Path $extract | Out-Null
    try {
        Write-Host "Codex $Version · official release asset · $target"
        Write-Host 'Downloading with resumable retries (HTTP/1.1) …'
        Invoke-ResilientDownload "$base/$asset" $archive
        Invoke-ResilientDownload "$base/codex-package_SHA256SUMS" $sums
        $line = Select-String -LiteralPath $sums -Pattern ([regex]::Escape($asset)) | Select-Object -First 1
        if (-not $line) { throw "Codex checksum for $asset was not found in the official manifest." }
        $expected = ($line.Line -split '\s+')[0].ToLowerInvariant()
        $actual = (Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash.ToLowerInvariant()
        if ($actual -ne $expected) { throw 'Codex package checksum mismatch; refusing to install a corrupted download.' }
        $tar = Get-Command tar.exe -ErrorAction SilentlyContinue
        if (-not $tar) { throw 'tar.exe is required to unpack the official Codex archive.' }
        & $tar.Source -xzf $archive -C $extract
        if ($LASTEXITCODE -ne 0) { throw 'Could not unpack the official Codex archive.' }
        $binary = Get-ChildItem -LiteralPath $extract -File -Recurse | Where-Object { $_.Name -like 'codex-*' } | Select-Object -First 1
        if (-not $binary) { throw 'Official Codex archive did not contain the expected binary.' }
        New-Item -ItemType Directory -Force -Path $CodexBinRoot | Out-Null
        Copy-Item -LiteralPath $binary.FullName -Destination (Join-Path $CodexBinRoot 'codex.exe') -Force
        Remove-Item -LiteralPath $archive,$sums -Force -ErrorAction SilentlyContinue
        Remove-Item -LiteralPath $versionRoot -Recurse -Force -ErrorAction SilentlyContinue
        Write-Host "✓ Codex $Version installed from the official release archive"
    } finally {
        Remove-Item -LiteralPath $extract -Recurse -Force -ErrorAction SilentlyContinue
    }
}
function Get-AntigravityLatestVersion { return Get-GitHubReleaseVersion $AntigravityReleasesApiUrl }
function Get-InstalledLazyVersion {
    $file = Join-Path $InstallRoot 'package.json'
    if (-not (Test-Path -LiteralPath $file -PathType Leaf)) { return '' }
